package io.github.diodeme.ji.host;

import java.nio.charset.StandardCharsets;
import java.security.KeyFactory;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.security.Signature;
import java.security.spec.X509EncodedKeySpec;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/** Host-owned one-use device challenge bound to a single transport connection. */
public final class HostDeviceChallengeService {
    private static final Duration TTL = Duration.ofMinutes(2);
    private final HostDeviceRegistry devices;
    private final Clock clock;
    private final SecureRandom random;
    private final Map<String, Challenge> pending = new ConcurrentHashMap<>();

    public HostDeviceChallengeService(HostDeviceRegistry devices, Clock clock, SecureRandom random) {
        this.devices = java.util.Objects.requireNonNull(devices, "devices");
        this.clock = java.util.Objects.requireNonNull(clock, "clock");
        this.random = java.util.Objects.requireNonNull(random, "random");
    }

    public Issued issue(String connectionId, String deviceId) {
        devices.authorize(deviceId, "session:read");
        byte[] nonce = new byte[32];
        random.nextBytes(nonce);
        Challenge challenge = new Challenge(connectionId, deviceId, nonce, clock.instant().plus(TTL));
        pending.put(connectionId, challenge);
        return new Issued(nonce, challenge.expiresAt());
    }

    public ConnectionPrincipal verify(
            String connectionId, String clientId, String deviceId, String transport,
            String routeId, byte[] nonce, byte[] signature) {
        Challenge challenge = pending.remove(connectionId);
        HostDeviceStore.Device device = devices.authorize(deviceId, "session:read");
        if (challenge == null || !challenge.deviceId().equals(deviceId)
                || !clock.instant().isBefore(challenge.expiresAt())
                || !MessageDigest.isEqual(challenge.nonce(), nonce)) {
            throw new SecurityException("device challenge rejected");
        }
        try {
            Signature verifier = Signature.getInstance("Ed25519");
            verifier.initVerify(KeyFactory.getInstance("Ed25519").generatePublic(
                    new X509EncodedKeySpec(device.publicKey())));
            verifier.update(payload(connectionId, deviceId, nonce));
            if (!verifier.verify(signature)) throw new SecurityException("device challenge rejected");
        } catch (java.security.GeneralSecurityException failure) {
            throw new SecurityException("device challenge rejected", failure);
        }
        HostRole role = device.hostRole();
        return new ConnectionPrincipal(connectionId, clientId, deviceId, "local-host",
                transport, routeId, role, role.scopes(), clock.instant());
    }

    public static byte[] payload(String connectionId, String deviceId, byte[] nonce) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            digest.update("ji-host-device-challenge-v1\0".getBytes(StandardCharsets.UTF_8));
            digest.update(connectionId.getBytes(StandardCharsets.UTF_8));
            digest.update((byte) 0);
            digest.update(deviceId.getBytes(StandardCharsets.UTF_8));
            digest.update((byte) 0);
            digest.update(nonce);
            return digest.digest();
        } catch (java.security.NoSuchAlgorithmException impossible) {
            throw new IllegalStateException(impossible);
        }
    }

    private record Challenge(String connectionId, String deviceId, byte[] nonce, Instant expiresAt) {
        private Challenge { nonce = nonce.clone(); }
        @Override public byte[] nonce() { return nonce.clone(); }
    }
    public record Issued(byte[] nonce, Instant expiresAt) {
        public Issued { nonce = nonce.clone(); }
        @Override public byte[] nonce() { return nonce.clone(); }
    }
}
